def same(left: Any, right: Any) -> bool:
    try:
        return json.dumps(left, sort_keys=True, allow_nan=False) == json.dumps(right, sort_keys=True, allow_nan=False)
    except (ValueError, TypeError, OverflowError, RecursionError):
        return False


def amend_model_packet(previous: dict[str, Any]) -> dict[str, Any]:
    value = deepcopy(previous)
    value["predecessors"].append("MET-REPAIR-006")
    value["allowedPaths"].append("tests/model/test_lifecycle_contracts.py")
    for field, additions in EXTRA.items():
        value[field].extend(additions)
    return value


def validate_inventory_edit(before: Any, after: Any) -> list[str]:
    """Only compare candidate bytes. No exec, import, eval or AST compilation."""
    change = EXPECTED_RECORD["testChange"]
    if not isinstance(before, bytes) or hashlib.sha256(before).hexdigest() != change["beforeSha256"]:
        return ["inventory baseline must match the pinned original bytes"]
    if not isinstance(after, bytes):
        return ["inventory candidate must be bytes"]
    old = change["beforePredicate"].encode("utf-8")
    new = change["afterPredicate"].encode("utf-8")
    if before.count(old) != 1:
        return ["original predicate must occur exactly once"]
    prefix, suffix = before.split(old)
    if (hashlib.sha256(prefix).hexdigest() != change["prefixSha256"]
            or hashlib.sha256(suffix).hexdigest() != change["suffixSha256"]):
        return ["inventory prefix/suffix pins differ"]
    if after != prefix + new + suffix:
        return ["only the exact additive required-five inventory predicate is authorized"]
    return []


def validate_model_api_inventory(packets: Any, record: Any, snapshots: Any) -> list[str]:
    errors: list[str] = []
    if not same(record, EXPECTED_RECORD):
        errors.append("model inventory amendment evidence or scope changed")
    if not isinstance(packets, dict):
        return [*errors, "model inventory authority requires a packet mapping"]
    if len(packets) != 194:
        errors.append("current catalog requires exactly 194 packets")
    if not same(packets.get("MET-REPAIR-006"), EXPECTED_META):
        errors.append("MET-REPAIR-006 whole-packet scope changed")
    if not same(packets.get("CON-MODEL-001"), amend_model_packet(EXPECTED_BEFORE)):
        errors.append("CON-MODEL-001 must retain the prior fixture grant plus only the exact inventory delta")
    if not isinstance(snapshots, dict):
        return [*errors, "pinned input byte mapping required"]
    pins = {**EXPECTED_RECORD["protectedFiles"], **{
        f"task-packets/{packet_id}.yaml": digest
        for packet_id, digest in EXPECTED_RECORD["packetDigests"].items()
    }}
    if set(snapshots) != set(pins):
        errors.append("exact pinned input inventory required")
    for path, digest in pins.items():
        raw = snapshots.get(path)
        if not isinstance(raw, bytes) or hashlib.sha256(raw).hexdigest() != digest:
            errors.append("missing or changed pinned input: " + path)
    return errors


def load_inventory_inputs(root: Path) -> dict[str, bytes]:
    paths = [*EXPECTED_RECORD["protectedFiles"], *(
        f"task-packets/{packet_id}.yaml" for packet_id in EXPECTED_RECORD["packetDigests"]
    )]
    snapshots = {}
    for path in paths:
        source = root / path
        if source.is_symlink() or not source.is_file() or source.resolve() != root / path:
            raise ValueError("pinned input must be a regular non-linked file: " + path)
        snapshots[path] = source.read_bytes()
    return snapshots


def main() -> int:
    try:
        packets = {p.stem: safe_yaml_load(p.read_text(encoding="utf-8"))
                   for p in sorted((ROOT / "task-packets").glob("*.yaml"))}
        record = json.loads((ROOT / "architecture/model-api-inventory-amendment.json").read_text())
        errors = validate_model_api_inventory(packets, record, load_inventory_inputs(ROOT))
    except (OSError, ValueError, TypeError, yaml.YAMLError) as exc:
        print("Model inventory scope unavailable: " + type(exc).__name__)
        return 1
    for error in errors:
        print("ERROR: " + error)
    if not errors:
        print("Model inventory authority valid: 194 packets; exact predicate grant; product/native acceptance unproven.")
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main())
